INSERT INTO questions (id, lesson_id, position, prompt, explanation) VALUES
(61, 6, 1, $$Aşağıdakilerden hangisi doğrudur?$$, $$Derin öğrenme makine öğrenmesinin, makine öğrenmesi de yapay zekanın bir alt kümesidir.$$),
(62, 6, 2, $$Etiketli verilerle model eğitmeye ne ad verilir?$$, $$Denetimli öğrenmede her örneğin doğru cevabı (etiketi) bilinir.$$),
(63, 6, 3, $$Model eğitim verisinde çok başarılı, yeni veride başarısızsa bu duruma ne denir?$$, $$Overfitting (aşırı öğrenme), modelin genellemek yerine eğitim verisini ezberlemesidir.$$),
(64, 6, 4, $$Müşterileri, etiket olmadan benzer davranışlarına göre gruplamak hangi yöntemin örneğidir?$$, $$Kümeleme (clustering), etiketsiz veride benzer örnekleri gruplayan denetimsiz bir yöntemdir.$$),
(71, 7, 1, $$Pandas'ta iki boyutlu, tablo benzeri temel veri yapısı hangisidir?$$, $$DataFrame satır ve sütunlardan oluşan iki boyutlu bir tablodur; Series ise tek bir sütun gibidir.$$),
(72, 7, 2, $$Bir CSV dosyasını DataFrame olarak okumak için hangi fonksiyon kullanılır?$$, $$pd.read_csv('dosya.csv') dosyayı okuyup bir DataFrame döndürür.$$),
(73, 7, 3, $$Eksik değerleri tespit etmek için hangi metot kullanılır?$$, $$isna() her hücrenin eksik olup olmadığını döner; dropna() siler, fillna() doldurur.$$),
(74, 7, 4, $$Puanların şehre göre ortalamasını almak için hangi ifade doğrudur?$$, $$groupby('sehir') veriyi şehre göre gruplar, ['puan'].mean() her grubun ortalamasını hesaplar.$$),
(81, 8, 1, $$Bir evin fiyatını tahmin etmek hangi tür problemdir?$$, $$Fiyat sürekli bir değerdir; sürekli değer tahmini regresyon problemidir.$$),
(82, 8, 2, $$Veriyi eğitim ve test kümelerine ayırmanın amacı nedir?$$, $$Test kümesi, modelin genelleme yeteneğini ölçmek için eğitimde kullanılmaz.$$),
(83, 8, 3, $$scikit-learn'de bir modeli eğitmek için hangi metot çağrılır?$$, $$scikit-learn modelleri fit(X, y) ile eğitilir, predict(X) ile tahmin yapar.$$),
(84, 8, 4, $$Dengesiz bir veri setinde yalnızca doğruluk metriğine bakmak neden yanıltıcı olabilir?$$, $$Azınlık sınıfını hiç bulamayan bir model bile yüksek doğruluk alabilir; precision ve recall da incelenmelidir.$$),
(91, 9, 1, $$LLM'lerin metni işlerken kullandığı en küçük birime ne ad verilir?$$, $$Modeller metni token'lara böler; bir token bir kelime, kelime parçası veya noktalama olabilir.$$),
(92, 9, 2, $$Prompt içinde modele birkaç örnek giriş-çıkış vermek hangi teknik olarak bilinir?$$, $$Few-shot prompting, istenen kalıbı örneklerle göstererek modelin doğru formatı yakalamasına yardım eder.$$),
(93, 9, 3, $$Modelin kendinden emin şekilde yanlış bilgi üretmesine ne denir?$$, $$Halüsinasyon, modelin dayanağı olmayan bilgiyi doğruymuş gibi üretmesidir.$$),
(94, 9, 4, $$Modeli harici, doğrulanmış belgelerle besleyerek cevap üretmesini sağlayan yaklaşım hangisidir?$$, $$RAG, ilgili belgeleri bulup prompt'a ekleyerek modelin doğrulanmış bilgiyle cevap vermesini sağlar.$$);
