                     difficulty, duration_min, xp_reward, star_x, star_y, sort_order) VALUES
(6, 'yapay-zekaya-giris', 2, $$Yapay Zekaya Giriş$$,
 $$Yapay zeka, makine öğrenmesi ve derin öğrenme arasındaki farkı kullanım alanlarıyla öğren.$$,
 ARRAY[$$Yapay zeka, makine öğrenmesi ve derin öğrenmeyi ayırt etmek$$, $$Denetimli ve denetimsiz öğrenmeyi tanımak$$,
       $$Eğitim ve test verisinin rolünü kavramak$$, $$Yapay zekanın etik sorumluluklarını tartışmak$$],
 ARRAY[$$Yapay zeka, insan zekası gerektiren görevleri yerine getirebilen sistemlerin genel adıdır. Makine öğrenmesi bu alanın bir alt kümesidir: Kuralları tek tek yazmak yerine sistemin örneklerden öğrenmesini sağlar. Derin öğrenme ise çok katmanlı yapay sinir ağlarıyla çalışan bir makine öğrenmesi yaklaşımıdır.$$,
       $$Denetimli öğrenmede model, doğru cevapları (etiketleri) bilinen örneklerden öğrenir; e-postaların spam olup olmadığını tahmin etmek gibi. Denetimsiz öğrenmede etiket yoktur; model verideki gizli grupları ve örüntüleri kendisi bulur.$$,
       $$Bir modelin gerçekten öğrenip öğrenmediğini anlamak için veri eğitim ve test olarak ayrılır. Model eğitim verisini ezberleyip yeni veride başarısız oluyorsa buna aşırı öğrenme (overfitting) denir. Verinin ve modellerin önyargı taşıyabileceğini unutmamak da sorumlu yapay zekanın parçasıdır.$$],
 'aircAruvnKk', 'BEGINNER', 30, 100, 600, 200, 1),
(7, 'pandas-ile-veri-analizi', 2, $$Pandas ile Veri Analizi$$,
 $$DataFrame'lerle veri yükle, temizle, filtrele ve grupla; ham veriden içgörü çıkar.$$,
 ARRAY[$$CSV dosyalarını DataFrame olarak yüklemek$$, $$Eksik verileri bulmak ve temizlemek$$,
       $$Filtreleme ve sıralama yapmak$$, $$groupby ile özet istatistikler çıkarmak$$],
 ARRAY[$$Pandas, Python'un veri analizi kütüphanesidir. Temel yapısı DataFrame, satır ve sütunlardan oluşan bir tabloya benzer: pd.read_csv('veri.csv') ile bir dosyayı saniyeler içinde analiz edilebilir hâle getirirsin.$$,
       $$Gerçek veri neredeyse hiç temiz değildir. isna() ile eksik değerleri bulur, dropna() ile atar ya da fillna() ile doldurursun. Koşullu filtreleme (df[df['puan'] > 80]) ve sıralama (sort_values) veriyi anlamanın ilk adımlarıdır.$$,
       $$groupby, veriyi bir sütuna göre gruplayıp her grup için özet çıkarmanı sağlar: Şehir bazında ortalama puan gibi. Bu projedeki Şehir Işıkları sıralaması da aynı fikrin SQL'deki karşılığıyla hesaplanıyor.$$],
 'ZyhVh-qRZPA', 'INTERMEDIATE', 40, 150, 700, 110, 2),
(8, 'makine-ogrenmesinin-temelleri', 2, $$Makine Öğrenmesinin Temelleri$$,
 $$Regresyon ve sınıflandırmayı tanı; bir modeli eğit, değerlendir ve doğru metriği seç.$$,
 ARRAY[$$Regresyon ile sınıflandırmayı ayırt etmek$$, $$Veriyi eğitim ve test kümelerine ayırmak$$,
       $$Doğruluk, kesinlik ve duyarlılık metriklerini yorumlamak$$, $$Özellik (feature) seçiminin önemini kavramak$$],
 ARRAY[$$Makine öğrenmesi problemleri çoğunlukla iki türdür: Regresyon sürekli bir değeri tahmin eder (ev fiyatı gibi), sınıflandırma ise bir kategori seçer (e-posta spam mı değil mi gibi).$$,
       $$Tipik bir akışta veri eğitim ve test kümelerine ayrılır (örneğin %80/%20). Model eğitim kümesinde öğrenir, test kümesinde hiç görmediği verilerle sınanır. scikit-learn gibi kütüphaneler fit() ile eğitimi, predict() ile tahmini birkaç satıra indirir.$$,
       $$Doğru metriği seçmek kritiktir. Dengesiz veride yalnızca doğruluğa (accuracy) bakmak yanıltıcı olabilir: Hastaların %1'inin hasta olduğu bir veri setinde herkese sağlıklı diyen model %99 doğruluk alır ama işe yaramaz. Bu yüzden kesinlik (precision) ve duyarlılık (recall) da incelenir.$$],
 'ukzFI9rgwfU', 'INTERMEDIATE', 45, 150, 810, 190, 3),
(9, 'buyuk-dil-modelleri', 2, $$Büyük Dil Modelleri ve Prompt Mühendisliği$$,
